INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CI001', 'HDSAT-RW-M21-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Origami (折り紙) is the art and technique of folding paper. It also refers to the two- and three-dimensional forms created in the process. The use of the term has been extended in modern times to include other materials such as metal, textiles, and it is also used in the biological sciences to describe folded structures like DNA. Although the word origami has Japanese roots, the practice itself is universal and its origin remains unknown. The goal is to transform a flat square sheet of paper into a finished sculpture through folding and sculpting techniques. Modern origami practitioners generally discourage the use of cuts, glue, or markings on the paper. Origami folders often use the Japanese word kirigami to refer to designs which use cuts. In the detailed Japanese classification, origami is divided into stylized ceremonial origami (儀礼折り紙, girei origami) and recreational origami (遊戯折り紙, yūgi origami), and only recreational origami is generally recognized as origami. In Japan, ceremonial origami is generally called "origata" (ja:折形) to distinguish it from recreational origami. The term "origata" is one of the old terms for origami. The small number of basic origami folds can be combined in a variety of ways to make intricate designs. The best-known origami model is the Japanese paper crane. In general, these designs begin with a square sheet of paper whose sides may be of different colors, prints, or patterns.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Origami is a paper-folding art with Japanese terminology but universal practice, and modern folders generally avoid cuts and glue."}, {"id": "B", "text": "Origami has a single documented place of origin."}, {"id": "C", "text": "Origami is practiced only in Japan and only for ceremonies."}, {"id": "D", "text": "Origami is a Japanese art that requires cutting and gluing paper."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Origami", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Origami', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CI001', 'A', ARRAY['A']::TEXT[], 'The passage defines origami, notes its uncertain origins, and explains the conventions and classifications of the practice.', '{"D": "The text says modern practitioners generally discourage cuts, glue, and markings.", "B": "The text says the practice is universal and its origin remains unknown.", "C": "The text says haiku today are written worldwide and distinguishes ceremonial from recreational origami."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-INF001', 'HDSAT-RW-M21-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Origami (折り紙) is the art and technique of folding paper. It also refers to the two- and three-dimensional forms created in the process. The use of the term has been extended in modern times to include other materials such as metal, textiles, and it is also used in the biological sciences to describe folded structures like DNA. Although the word origami has Japanese roots, the practice itself is universal and its origin remains unknown. The goal is to transform a flat square sheet of paper into a finished sculpture through folding and sculpting techniques. Modern origami practitioners generally discourage the use of cuts, glue, or markings on the paper. Origami folders often use the Japanese word kirigami to refer to designs which use cuts. In the detailed Japanese classification, origami is divided into stylized ceremonial origami (儀礼折り紙, girei origami) and recreational origami (遊戯折り紙, yūgi origami), and only recreational origami is generally recognized as origami. In Japan, ceremonial origami is generally called "origata" (ja:折形) to distinguish it from recreational origami. The term "origata" is one of the old terms for origami. The small number of basic origami folds can be combined in a variety of ways to make intricate designs. The best-known origami model is the Japanese paper crane. In general, these designs begin with a square sheet of paper whose sides may be of different colors, prints, or patterns.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-INF001', 'D', ARRAY['D']::TEXT[], 'The passage explicitly assigns cut designs to kirigami, and origami proper avoids cuts.', '{"C": "The text says folders use the word kirigami for designs that use cuts.", "B": "The ceremonial and recreational distinction concerns the purpose of the folding, not the use of cuts.", "A": "Bookbinding is not mentioned in the text."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-TS001', 'HDSAT-RW-M21-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Origami (折り紙) is the art and technique of folding paper. It also refers to the two- and three-dimensional forms created in the process. The use of the term has been extended in modern times to include other materials such as metal, textiles, and it is also used in the biological sciences to describe folded structures like DNA. Although the word origami has Japanese roots, the practice itself is universal and its origin remains unknown. The goal is to transform a flat square sheet of paper into a finished sculpture through folding and sculpting techniques. Modern origami practitioners generally discourage the use of cuts, glue, or markings on the paper. Origami folders often use the Japanese word kirigami to refer to designs which use cuts. In the detailed Japanese classification, origami is divided into stylized ceremonial origami (儀礼折り紙, girei origami) and recreational origami (遊戯折り紙, yūgi origami), and only recreational origami is generally recognized as origami. In Japan, ceremonial origami is generally called "origata" (ja:折形) to distinguish it from recreational origami. The term "origata" is one of the old terms for origami. The small number of basic origami folds can be combined in a variety of ways to make intricate designs. The best-known origami model is the Japanese paper crane. In general, these designs begin with a square sheet of paper whose sides may be of different colors, prints, or patterns.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that origami should permit cutting and gluing."}, {"id": "B", "text": "It traces the history of origami from ancient China to modern Europe."}, {"id": "C", "text": "It defines origami, explains its techniques and rules, and distinguishes its ceremonial and recreational forms."}, {"id": "D", "text": "It compares origami with sculpture in stone and metal."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Origami", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Origami', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-TS001', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to technique and then to classification.', '{"B": "The text mentions no Chinese origin and calls the origin unknown.", "D": "Stone and metal appear only as materials the term has been extended to.", "A": "The text reports the convention against cuts without arguing for a change."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CE001', 'HDSAT-RW-M21-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Origami (折り紙) is the art and technique of folding paper. It also refers to the two- and three-dimensional forms created in the process. The use of the term has been extended in modern times to include other materials such as metal, textiles, and it is also used in the biological sciences to describe folded structures like DNA. Although the word origami has Japanese roots, the practice itself is universal and its origin remains unknown. The goal is to transform a flat square sheet of paper into a finished sculpture through folding and sculpting techniques. Modern origami practitioners generally discourage the use of cuts, glue, or markings on the paper. Origami folders often use the Japanese word kirigami to refer to designs which use cuts. In the detailed Japanese classification, origami is divided into stylized ceremonial origami (儀礼折り紙, girei origami) and recreational origami (遊戯折り紙, yūgi origami), and only recreational origami is generally recognized as origami. In Japan, ceremonial origami is generally called "origata" (ja:折形) to distinguish it from recreational origami. The term "origata" is one of the old terms for origami. The small number of basic origami folds can be combined in a variety of ways to make intricate designs. The best-known origami model is the Japanese paper crane. In general, these designs begin with a square sheet of paper whose sides may be of different colors, prints, or patterns.', 'Which quotation from the text most directly supports the claim that origami''s name is Japanese but its beginnings are unclear?', '[{"id": "A", "text": "Although the word origami has Japanese roots, the practice itself is universal and its origin remains unknown."}, {"id": "B", "text": "Origami is the art and technique of folding paper."}, {"id": "C", "text": "The small number of basic origami folds can be combined in a variety of ways to make intricate designs."}, {"id": "D", "text": "The best-known origami model is the Japanese paper crane."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Origami", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Origami', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CE001', 'A', ARRAY['A']::TEXT[], 'The correct quotation explicitly separates the Japanese word from the unknown origin of the practice.', '{"B": "This sentence defines the practice.", "C": "This sentence describes how folds combine.", "D": "This sentence identifies a famous model."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CI002', 'HDSAT-RW-M21-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Jazz is a music genre that originated in the African-American communities of New Orleans, Louisiana, in the late 19th and early 20th centuries. Its roots are in blues, ragtime, European harmony, African rhythmic rituals, spirituals, hymns, marches, vaudeville song, and dance music. Since the 1920s Jazz Age, it has been recognized as a major form of musical expression in both traditional and popular music. Jazz is characterized by swing and blue notes, complex chords, call and response vocals, polyrhythms and improvisation. As jazz spread around the world, it drew on national, regional, and local musical cultures, which gave rise to different styles. New Orleans jazz began in the early 1910s, combining earlier brass band marches, French quadrilles, biguine, ragtime and blues with collective polyphonic improvisation. However, jazz did not begin as a single musical tradition in New Orleans or elsewhere. In the 1930s, arranged dance-oriented swing big bands, Kansas City jazz (a hard-swinging, bluesy, improvisational style), and gypsy jazz (a style that emphasized musette waltzes) were the prominent styles. Bebop emerged in the 1940s, shifting jazz from danceable popular music toward a more challenging "musician''s music" which was played at faster tempos and used more chord-based improvisation. Cool jazz developed near the end of the 1940s, introducing calmer, smoother sounds and long, linear melodic lines.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Jazz is defined mainly by its use of written notation."}, {"id": "B", "text": "Jazz has remained unchanged since the 1920s."}, {"id": "C", "text": "Jazz originated in Europe and spread to the United States."}, {"id": "D", "text": "Jazz arose in African American communities in New Orleans, drew on many traditions, and developed distinct styles over time."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Jazz", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Jazz', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CI002', 'D', ARRAY['D']::TEXT[], 'The passage describes jazz''s origins, musical roots, defining features, and stylistic evolution.', '{"C": "The text says it originated in African American communities of New Orleans.", "B": "The text describes new styles such as swing, bebop, and cool jazz.", "A": "The text emphasizes improvisation, not notation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-INF002', 'HDSAT-RW-M21-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Jazz is a music genre that originated in the African-American communities of New Orleans, Louisiana, in the late 19th and early 20th centuries. Its roots are in blues, ragtime, European harmony, African rhythmic rituals, spirituals, hymns, marches, vaudeville song, and dance music. Since the 1920s Jazz Age, it has been recognized as a major form of musical expression in both traditional and popular music. Jazz is characterized by swing and blue notes, complex chords, call and response vocals, polyrhythms and improvisation. As jazz spread around the world, it drew on national, regional, and local musical cultures, which gave rise to different styles. New Orleans jazz began in the early 1910s, combining earlier brass band marches, French quadrilles, biguine, ragtime and blues with collective polyphonic improvisation. However, jazz did not begin as a single musical tradition in New Orleans or elsewhere. In the 1930s, arranged dance-oriented swing big bands, Kansas City jazz (a hard-swinging, bluesy, improvisational style), and gypsy jazz (a style that emphasized musette waltzes) were the prominent styles. Bebop emerged in the 1940s, shifting jazz from danceable popular music toward a more challenging "musician''s music" which was played at faster tempos and used more chord-based improvisation. Cool jazz developed near the end of the 1940s, introducing calmer, smoother sounds and long, linear melodic lines.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-INF002', 'B', ARRAY['B']::TEXT[], 'If bebop was less danceable and more oriented toward musicians, listening rather than dancing is the logical behavior.', '{"C": "The text contrasts bebop with dance-oriented swing and describes it as musician''s music.", "D": "The text says bebop moved away from danceable popular music.", "A": "The text says bebop used more chord-based improvisation, not that audiences rejected it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-TS002', 'HDSAT-RW-M21-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Jazz is a music genre that originated in the African-American communities of New Orleans, Louisiana, in the late 19th and early 20th centuries. Its roots are in blues, ragtime, European harmony, African rhythmic rituals, spirituals, hymns, marches, vaudeville song, and dance music. Since the 1920s Jazz Age, it has been recognized as a major form of musical expression in both traditional and popular music. Jazz is characterized by swing and blue notes, complex chords, call and response vocals, polyrhythms and improvisation. As jazz spread around the world, it drew on national, regional, and local musical cultures, which gave rise to different styles. New Orleans jazz began in the early 1910s, combining earlier brass band marches, French quadrilles, biguine, ragtime and blues with collective polyphonic improvisation. However, jazz did not begin as a single musical tradition in New Orleans or elsewhere. In the 1930s, arranged dance-oriented swing big bands, Kansas City jazz (a hard-swinging, bluesy, improvisational style), and gypsy jazz (a style that emphasized musette waltzes) were the prominent styles. Bebop emerged in the 1940s, shifting jazz from danceable popular music toward a more challenging "musician''s music" which was played at faster tempos and used more chord-based improvisation. Cool jazz developed near the end of the 1940s, introducing calmer, smoother sounds and long, linear melodic lines.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that jazz should return to its New Orleans roots."}, {"id": "B", "text": "It describes jazz''s origins and traits, then surveys the styles that developed over the decades."}, {"id": "C", "text": "It compares jazz with classical European harmony in detail."}, {"id": "D", "text": "It profiles a single jazz musician and his career."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Jazz", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Jazz', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-TS002', 'B', ARRAY['B']::TEXT[], 'The passage opens with origins and characteristics, then moves chronologically through styles.', '{"D": "No individual musician is named.", "C": "European harmony is listed as one root, not analyzed at length.", "A": "The text describes stylistic change without advocating a return."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CE002', 'HDSAT-RW-M21-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Jazz is a music genre that originated in the African-American communities of New Orleans, Louisiana, in the late 19th and early 20th centuries. Its roots are in blues, ragtime, European harmony, African rhythmic rituals, spirituals, hymns, marches, vaudeville song, and dance music. Since the 1920s Jazz Age, it has been recognized as a major form of musical expression in both traditional and popular music. Jazz is characterized by swing and blue notes, complex chords, call and response vocals, polyrhythms and improvisation. As jazz spread around the world, it drew on national, regional, and local musical cultures, which gave rise to different styles. New Orleans jazz began in the early 1910s, combining earlier brass band marches, French quadrilles, biguine, ragtime and blues with collective polyphonic improvisation. However, jazz did not begin as a single musical tradition in New Orleans or elsewhere. In the 1930s, arranged dance-oriented swing big bands, Kansas City jazz (a hard-swinging, bluesy, improvisational style), and gypsy jazz (a style that emphasized musette waltzes) were the prominent styles. Bebop emerged in the 1940s, shifting jazz from danceable popular music toward a more challenging "musician''s music" which was played at faster tempos and used more chord-based improvisation. Cool jazz developed near the end of the 1940s, introducing calmer, smoother sounds and long, linear melodic lines.', 'Which quotation from the text most directly supports the claim that jazz drew on many musical traditions?', '[{"id": "A", "text": "Jazz is a music genre that originated in the African-American communities of New Orleans, Louisiana, in the late 19th and early 20th centuries."}, {"id": "B", "text": "In the 1930s, arranged dance-oriented swing big bands were among the prominent styles."}, {"id": "C", "text": "Its roots are in blues, ragtime, European harmony, African rhythmic rituals, spirituals, hymns, marches, vaudeville song, and dance music."}, {"id": "D", "text": "Jazz is characterized by swing and blue notes, complex chords, call and response vocals, polyrhythms and improvisation."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Jazz", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Jazz', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CE002', 'C', ARRAY['C']::TEXT[], 'Only the correct quotation lists the varied traditions that fed into jazz.', '{"A": "This sentence gives the genre''s origin.", "D": "This sentence lists defining characteristics.", "B": "This sentence describes a later style."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CI003', 'HDSAT-RW-M21-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Haiku (俳句; English: , Japanese: [hä̀í.kɯ̈́] ) is a type of short-form poetry that originated in Japan. Traditional Japanese haiku consist of three phrases composed of 17 morae (called on in Japanese) in a 5, 7, 5 pattern that include a kireji or "cutting word" and a kigo or seasonal reference. However, haiku by classical Japanese poets, such as Matsuo Bashō, also deviate from the 17-on pattern and sometimes do not contain a kireji. Similar poems that do not adhere to these rules are generally classified as senryū. Haiku originated as an opening part of a larger Japanese genre of poetry called renga. These haiku, written as opening stanzas, were known as hokku and over time they began to be written as stand-alone poems. Haiku was given its current name by the Japanese writer Masaoka Shiki at the end of the 19th century. Originally from Japan, haiku today are written by authors worldwide. Haiku in English and haiku in other languages have different styles and traditions while still incorporating aspects of the traditional haiku form. Non-Japanese language haiku vary widely on how closely they follow traditional elements. Additionally, a minority movement within modern Japanese haiku (現代俳句, gendai-haiku), supported by Ogiwara Seisensui and his disciples, has varied from the tradition of 17 on as well as taking nature as their subject. In Japanese, haiku are traditionally printed as a single line, while haiku in English often appear as three lines, although variations exist.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All haiku in every language follow the 5-7-5 pattern exactly."}, {"id": "B", "text": "Haiku was invented in the 20th century by Masaoka Shiki."}, {"id": "C", "text": "Haiku is a long narrative poem that originated in China."}, {"id": "D", "text": "Haiku is a short Japanese poetic form with traditional rules that has been adapted widely and variably outside Japan."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Haiku", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Haiku', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CI003', 'D', ARRAY['D']::TEXT[], 'The passage defines haiku, explains its traditional elements, traces its history, and notes variation abroad.', '{"C": "The text calls it a type of short-form poetry that originated in Japan.", "A": "The text says non-Japanese haiku vary widely in how closely they follow traditional elements.", "B": "The text says Shiki gave the form its current name, not that he invented it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-INF003', 'HDSAT-RW-M21-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Haiku (俳句; English: , Japanese: [hä̀í.kɯ̈́] ) is a type of short-form poetry that originated in Japan. Traditional Japanese haiku consist of three phrases composed of 17 morae (called on in Japanese) in a 5, 7, 5 pattern that include a kireji or "cutting word" and a kigo or seasonal reference. However, haiku by classical Japanese poets, such as Matsuo Bashō, also deviate from the 17-on pattern and sometimes do not contain a kireji. Similar poems that do not adhere to these rules are generally classified as senryū. Haiku originated as an opening part of a larger Japanese genre of poetry called renga. These haiku, written as opening stanzas, were known as hokku and over time they began to be written as stand-alone poems. Haiku was given its current name by the Japanese writer Masaoka Shiki at the end of the 19th century. Originally from Japan, haiku today are written by authors worldwide. Haiku in English and haiku in other languages have different styles and traditions while still incorporating aspects of the traditional haiku form. Non-Japanese language haiku vary widely on how closely they follow traditional elements. Additionally, a minority movement within modern Japanese haiku (現代俳句, gendai-haiku), supported by Ogiwara Seisensui and his disciples, has varied from the tradition of 17 on as well as taking nature as their subject. In Japanese, haiku are traditionally printed as a single line, while haiku in English often appear as three lines, although variations exist.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-INF003', 'D', ARRAY['D']::TEXT[], 'The contrast between one-line Japanese printing and three-line English printing shows that presentation varies by language.', '{"A": "The text contrasts Japanese and English printing conventions.", "B": "The text explicitly says the conventions differ.", "C": "The text reports variation in line arrangement."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-TS003', 'HDSAT-RW-M21-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Haiku (俳句; English: , Japanese: [hä̀í.kɯ̈́] ) is a type of short-form poetry that originated in Japan. Traditional Japanese haiku consist of three phrases composed of 17 morae (called on in Japanese) in a 5, 7, 5 pattern that include a kireji or "cutting word" and a kigo or seasonal reference. However, haiku by classical Japanese poets, such as Matsuo Bashō, also deviate from the 17-on pattern and sometimes do not contain a kireji. Similar poems that do not adhere to these rules are generally classified as senryū. Haiku originated as an opening part of a larger Japanese genre of poetry called renga. These haiku, written as opening stanzas, were known as hokku and over time they began to be written as stand-alone poems. Haiku was given its current name by the Japanese writer Masaoka Shiki at the end of the 19th century. Originally from Japan, haiku today are written by authors worldwide. Haiku in English and haiku in other languages have different styles and traditions while still incorporating aspects of the traditional haiku form. Non-Japanese language haiku vary widely on how closely they follow traditional elements. Additionally, a minority movement within modern Japanese haiku (現代俳句, gendai-haiku), supported by Ogiwara Seisensui and his disciples, has varied from the tradition of 17 on as well as taking nature as their subject. In Japanese, haiku are traditionally printed as a single line, while haiku in English often appear as three lines, although variations exist.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that English haiku should abandon seasonal references."}, {"id": "B", "text": "It provides a close reading of one poem by Bashō."}, {"id": "C", "text": "It compares haiku with the sonnet and the epic."}, {"id": "D", "text": "It defines the form and its rules, explains its origin in renga, and describes its global adaptation."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Haiku", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Haiku', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
