 knowledge without writing?', '[{"id": "A", "text": "Religions such as Buddhism, Hinduism, Catholicism, Yazidism and Jainism have used oral tradition, in parallel to writing, to transmit their canonical scriptures."}, {"id": "B", "text": "African societies have broadly been labelled oral civilisations, contrasted with literate civilisations."}, {"id": "C", "text": "Oral tradition is a medium of communication for a society to transmit oral history, oral literature, oral law and other knowledge across generations without a writing system, or in parallel to a writing system."}, {"id": "D", "text": "The information is mentally recorded by oral repositories, sometimes termed \"walking libraries\", who are usually also performers."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Oral tradition", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Oral_tradition', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
