INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CI007', 'HDSAT-RW-M21-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Bookbinding is the process of building a book, usually in codex format, from an ordered stack of paper sheets with one''s hands and tools, or in modern publishing, by a series of automated processes. To bind a book, groups of pages are joined together, often by thread or adhesive but other options exist such as loose-leaf rings, binding posts, twin-loop spine coils, plastic spiral coils, and plastic spine combs. A cover to protect the contents, usually bearing publication information such as title and author, is generally attached; this can be as simple as a single sheet of paper or an elaborate construction of boards covered in cloth, leather, parchment, etc. with many types of decoration. The process of making books varies significantly by time period and geography/culture. Mechanised bookbinding was introduced in the 19th century with the industrial revolution, alongside machine papermaking, faster methods of leather tanning, and other changes in manufacturing that affected the book. The trade of bookbinding includes the binding of blank books and printed books. Blank books, or stationery bindings, are books planned to be written in. These include accounting ledgers, guestbooks, logbooks, notebooks, manifold books, day books, diaries, and sketchbooks. Printed books are produced through letterpress printing, offset lithography, or other printing techniques and their binding practices include fine binding, edition binding, publisher''s bindings, and library binding.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All books are bound with thread and leather."}, {"id": "B", "text": "Bookbinding joins pages and adds a cover through varied methods that changed with industrialization."}, {"id": "C", "text": "Bookbinding is the process of writing and editing a manuscript."}, {"id": "D", "text": "Mechanized binding ended the production of handmade books."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Bookbinding", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Bookbinding', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CI007', 'B', ARRAY['B']::TEXT[], 'The passage defines binding, surveys materials and methods, and notes the effect of mechanization.', '{"C": "The text defines binding as building a book from ordered pages.", "A": "The text lists adhesives, rings, posts, coils, and combs as alternatives.", "D": "The text says mechanized binding was introduced in the 19th century, not that handmade binding ended."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
