[{"id": "A", "text": "It defines bookbinding, describes methods and materials, and distinguishes types of binding work."}, {"id": "B", "text": "It narrates the history of a single printing press."}, {"id": "C", "text": "It compares European and Asian bookbinding techniques in detail."}, {"id": "D", "text": "It explains how to write a novel."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Bookbinding", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Bookbinding', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
