INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CE007', 'HDSAT-RW-M21-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Bookbinding is the process of building a book, usually in codex format, from an ordered stack of paper sheets with one''s hands and tools, or in modern publishing, by a series of automated processes. To bind a book, groups of pages are joined together, often by thread or adhesive but other options exist such as loose-leaf rings, binding posts, twin-loop spine coils, plastic spiral coils, and plastic spine combs. A cover to protect the contents, usually bearing publication information such as title and author, is generally attached; this can be as simple as a single sheet of paper or an elaborate construction of boards covered in cloth, leather, parchment, etc. with many types of decoration. The process of making books varies significantly by time period and geography/culture. Mechanised bookbinding was introduced in the 19th century with the industrial revolution, alongside machine papermaking, faster methods of leather tanning, and other changes in manufacturing that affected the book. The trade of bookbinding includes the binding of blank books and printed books. Blank books, or stationery bindings, are books planned to be written in. These include accounting ledgers, guestbooks, logbooks, notebooks, manifold books, day books, diaries, and sketchbooks. Printed books are produced through letterpress printing, offset lithography, or other printing techniques and their binding practices include fine binding, edition binding, publisher''s bindings, and library binding.', 'Which quotation from the text most directly supports the claim that binding methods vary across cultures and eras?', '[{"id": "A", "text": "A cover to protect the contents, usually bearing publication information such as title and author, is generally attached."}, {"id": "B", "text": "Bookbinding is the process of building a book, usually in codex format, from an ordered stack of paper sheets."}, {"id": "C", "text": "The process of making books varies significantly by time period and geography/culture."}, {"id": "D", "text": "Mechanised bookbinding was introduced in the 19th century with the industrial revolution."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Bookbinding", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Bookbinding', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CE007', 'C', ARRAY['C']::TEXT[], 'The correct quotation directly states that bookmaking varies by period and culture.', '{"B": "This sentence defines the process.", "A": "This sentence describes the cover.", "D": "This sentence dates mechanized binding."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M21-CI008', 'HDSAT-RW-M21-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Color theory, or more specifically traditional color theory, is a historical body of knowledge describing the behavior of colors — namely in color mixing, color contrast effects, color harmony, color schemes and color symbolism. Color theory and color science both study color and its existence. Traditional color theory tends to be more subjective and have artistic applications, while color science tends to be more objective and have functional applications, such as in chemistry, astronomy or color reproduction. However, there is much intertwining between the two throughout history, and they tend to aid each other in their own evolutions. Color theory can be considered a science unto itself that uses the relationship between human color perception and the interactions of colors together to build their palettes, schemes, and color mixes. Importantly, color theory relies upon objective standards in-order to be consistent in color mixing and presentation – i.e. to achieve the ideal color and effect, your ratios of colors must be consistent and often exact. As for functional applications, color theory, in tandem with color science, is what allows humans to achieve ideal camouflage, design paints that disperse more heat, and is often used by theme parks like Disney to achieve their ideal aesthetic. Color theory dates back at least as far as Aristotle''s treatise On Colors and Bharata''s Nāṭya Shāstra.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Color theory was invented by Disney in the 20th century."}, {"id": "B", "text": "Color theory is entirely subjective and has no practical applications."}, {"id": "C", "text": "Color theory is a branch of astronomy that studies stars."}, {"id": "D", "text": "Color theory is a body of knowledge about color mixing and harmony that overlaps with objective color science and has practical uses."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Color theory", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Color_theory', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-CI008', 'D', ARRAY['D']::TEXT[], 'The passage defines color theory, contrasts it with color science, and gives examples of its applications.', '{"C": "The text mentions astronomy as an application of color science, not as color theory itself.", "B": "The text describes applications such as camouflage and heat-dispersing paints.", "A": "The text says color theory dates back at least to Aristotle and Bharata."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
