INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M21-INF008', 'D', ARRAY['D']::TEXT[], 'Consistent, exact color mixing depends on measurement and standards, not improvisation.', '{"A": "The text says consistency in mixing and presentation depends on objective standards.", "C": "The text says your ratios of colors must be consistent and often exact.", "B": "Primary colors are not the focus of the passage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
